{
  "schema[string]": "issuestack.task.v3",
  "nonce[string]": "issuescratch-sixteen-fewshot-independent-audit-20261030-v1",
  "ordinal[number|null]": null,
  "source[object<Source>]": {
    "issue[number]": 1,
