  "interpretation[object<Interpretation>]": {
    "revised_instruction[string]": "Independently audit the 16 positive and two negative three-scratchpad examples in BestNameYet/IssueScratch AGENTS.md at commit cc9a003b3f852a19133b075ae93f5cb7cde8c155. Judge whether the positive examples contain paraphrases, cumulative/appended text, or genuinely distinct contributions, and whether increasing intensity along a single undisclosed property is visibly defensible. Independently classify the raw JSON before consulting existing author annotations. Report any violations, ambiguous cases, and concrete repairs without modifying IssueScratch.",
    "user_intent[object<UserIntent>]": {
      "goal[string]": "Obtain a genuinely independent second review of the IssueScratch few-shot examples, especially to detect hidden paraphrasing and appended expansions.",
      "expected_outcome[string]": "For each of 18 examples, an independent comparison of scratchpad_1 to scratchpad_2 and scratchpad_2 to scratchpad_3, classification of each transition, justification, disagreement with existing labels, separate examination of observable intensity progression, and a summary verdict with suggested repairs.",
      "requested_abstraction_level[string]": "Fine-grained semantic and compositional analysis rather than superficial text similarity or acceptance of the examples' existing annotations.",
      "requested_action_scope[string]": "Read-only independent audit; record findings in this IssueStack job and its scratchpad. Do not modify IssueScratch source examples or reveal the agent's selected latent property."
    }
  },
  "requirements[array<Requirement>]": [
    {
      "id[string]": "R1",
      "description[string]": "Audit the exact source revision and all 18 examples",
      "acceptance_criteria[array<AcceptanceCriterion>]": [
        {
          "text[string]": "Fetch the file at the specified commit and confirm its SHA and sixteen positive plus two negative examples."
        },
        {
          "text[string]": "Evaluate the scratchpad text independently before reading the preexisting classification annotations."
        }
      ]
    },
    {
      "id[string]": "R2",
      "description[string]": "Evaluate semantic independence for both transitions in every example",
      "acceptance_criteria[array<AcceptanceCriterion>]": [
        {
          "text[string]": "Provide separate classifications for 1→2 and 2→3 across all 18 examples: independent contribution, paraphrase, appended expansion, or explicitly ambiguous."
        },
        {
          "text[string]": "Explain what new proposition or contribution exists for independent pairs, and what is repeated or merely appended in invalid pairs."
        },
        {
          "text[string]": "Identify any false-positive claims of independence among the sixteen examples, and verify that the two negative controls fail for their specified reasons."
        }
      ]
    },
    {
      "id[string]": "R3",
      "description[string]": "Assess ordinal intensity and non-repetition without disclosing properties",
      "acceptance_criteria[array<AcceptanceCriterion>]": [
        {
          "text[string]": "Separately assess whether each positive triple exhibits a plausible strictly increasing ordering along one coherent qualitative property."
        },
        {
          "text[string]": "Assess the claimed non-repetition of properties across the sixteen examples to the extent observable, without naming, recording or exposing which property was selected."
        },
        {
          "text[string]": "Flag any unverifiable latent-property assertions rather than claiming proof without access to evidence."
        }
      ]
    },
    {
      "id[string]": "R4",
      "description[string]": "Return independently justified verdicts and correction proposals",
      "acceptance_criteria[array<AcceptanceCriterion>]": [
        {
          "text[string]": "Produce a table for all sixteen positive examples and both negative controls with both transition classifications, ordering assessment and evidence."
        },
        {
          "text[string]": "Conclude with counts of pass, fail and ambiguous examples and identify precise edits needed for any weak examples."
        },
        {
          "text[string]": "Store report, source revision, observations, and evidence in the mapped Issue #3 scratchpad and Issue #2 job record; do not make source changes."
        }
      ]
    }
  ],
  "constraints[array<Constraint>]": [
    {
      "id[string]": "C1",
      "description[string]": "Do not treat source annotations or author claims as independent verification; classify raw text first.",
      "source[string]": "User explicitly requests independent verification.",
      "applies_to_requirement_ids[array<Reference>]": [
        {
          "id[string]": "R1"
        },
        {
          "id[string]": "R2"
        },
        {
          "id[string]": "R4"
        }
      ]
    },
    {
      "id[string]": "C2",
      "description[string]": "Distinguish paraphrase, appended/cumulative expansion, and genuinely independent substantive contributions; higher intensity alone cannot excuse semantic duplication.",
      "source[string]": "IssueScratch AGENTS.md distinctness rule and user instructions.",
      "applies_to_requirement_ids[array<Reference>]": [
        {
          "id[string]": "R2"
        },
        {
          "id[string]": "R3"
        }
      ]
    },
    {
      "id[string]": "C3",
      "description[string]": "Keep the chosen properties undisclosed; judge only observable ordering and note epistemic limits of verifying unobserved choices.",
      "source[string]": "User request for unrevealed nonrepeating properties.",
      "applies_to_requirement_ids[array<Reference>]": [
        {
          "id[string]": "R3"
        }
      ]
    },
    {
      "id[string]": "C4",
      "description[string]": "This is an audit, not authorization to edit IssueScratch or alter the inspected source revision.",
      "source[string]": "Requested independent verification.",
      "applies_to_requirement_ids[array<Reference>]": [
        {
          "id[string]": "R1"
        },
        {
          "id[string]": "R4"
        }
      ]
    }
  ],
